{"code":"import pandas as pd, numpy as np, statsmodels.api as sm
from scipy.stats import pearsonr
D=pd.read_csv('data/explore.csv');
y=D.species_richness
for c in D.columns[2:-1]:
 m=sm.OLS(y, sm.add_constant(pd.concat([D[[c]],pd.get_dummies(D.region,drop_first=True,dtype=float)],axis=1))).fit()
